interface MemberRepository {
    boolean existsByEmail(String email);
    void save(String email);
}

// 本番では JPA の実装が入る場所。テストでは HashSet で十分
class InMemoryMemberRepository implements MemberRepository {
    final Set<String> emails = new HashSet<>();
    public boolean existsByEmail(String email) { return emails.contains(email); }
    public void save(String email) { emails.add(email); }
}

// 業務ロジック:メールアドレスの重複は登録させない
class MemberService {
    private final MemberRepository repository;
    MemberService(MemberRepository repository) { this.repository = repository; }

    void register(String email) {
        String normalized = email.strip().toLowerCase(); // ここを変えてみよう:toLowerCase() を消す
        if (repository.existsByEmail(normalized)) {
            throw new IllegalStateException("登録済みのメールです: " + normalized);
        }
        repository.save(normalized);
    }
}

// --- ここからテストのつもり(本物は JUnit で書く) ---
void check(String title, boolean ok) {
    System.out.println((ok ? "✔ " : "✘ ") + title);
}

InMemoryMemberRepository repo = new InMemoryMemberRepository();
MemberService service = new MemberService(repo);   // new するだけ。Spring もDBも不要

service.register("taro@example.com");
check("1件目は登録できる", repo.emails.contains("taro@example.com"));

boolean rejected;
try {
    service.register(" TARO@example.com ");   // 大文字・空白違いの同じアドレス
    rejected = false;
} catch (IllegalStateException e) {
    rejected = true;
    System.out.println("  例外メッセージ: " + e.getMessage());
}
check("大文字・空白違いでも重複として弾く", rejected);
check("登録件数は1件のまま", repo.emails.size() == 1);

import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.stereotype.*;

// 3層を Spring のコンテナで組み立てる(Spring Boot ならコンポーネントスキャンが自動でやる部分)
interface MemberRepository {
    void save(String name);
    List<String> findAll();
}

@Repository
class InMemoryMemberRepository implements MemberRepository {
    private final List<String> data = new ArrayList<>();
    public void save(String name) { data.add(name); }
    public List<String> findAll() { return List.copyOf(data); }
}

@Service
class MemberService {
    private final MemberRepository repository;   // インターフェースに依存する
    MemberService(MemberRepository repository) { this.repository = repository; }

    String register(String name) {
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("名前が空です");
        }
        repository.save(name.strip());
        return name.strip() + " さんを登録(会員数 "
                + repository.findAll().size() + ")";
    }
}

@Controller
class MemberController {
    private final MemberService service;         // Repository は知らない
    MemberController(MemberService service) { this.service = service; }

    String post(String name) {
        try {
            return "200 OK: " + service.register(name);
        } catch (IllegalArgumentException e) {
            return "400 Bad Request: " + e.getMessage();
        }
    }
}

// ここを変えてみよう:InMemoryMemberRepository.class を消すと、起動時にどんなエラーになる?
var ctx = new AnnotationConfigApplicationContext(
        MemberController.class,
        MemberService.class,
        InMemoryMemberRepository.class);

MemberController controller = ctx.getBean(MemberController.class);
System.out.println(controller.post("山田太郎"));
System.out.println(controller.post("  "));
System.out.println(controller.post("佐藤花子"));

// コンテナが作った Bean はシングルトン:何度 getBean しても同じインスタンス
MemberService s1 = ctx.getBean(MemberService.class);
MemberService s2 = ctx.getBean(MemberService.class);
System.out.println("同じ Service? " + (s1 == s2));
System.out.println("Repository の中身: " + ctx.getBean(MemberRepository.class).findAll());
ctx.close();

